from h34 import *
M=mcq;F=tf;S=short;N=num
chapter(3,'english','the-big-laddoo','The Big Laddoo',
 ('If everything became one','A funny poem imagines what would happen if all the laddoos joined into one huge laddoo, all the children into one huge child and all the seas into one huge sea. Then the huge child lifts the huge laddoo and throws it into the huge sea, making a giant splash. In this chapter you will enjoy the poem, think about things that are big, round and floating, match animals with their partners and read about the festival of khichdi.'),
 [('The poem and its pattern',['The poem plays with one idea again and again: what if many small things became one very big thing.','It talks about laddoos, children and seas. In each case, many small ones join to make one big one.','The word BIG is repeated so that we feel how huge each thing is.','At the end the big child throws the big laddoo into the big sea, and the poem ends with a big splish-splash.','Splish-splash is a sound word. It copies the sound of water, so we can almost hear it.','A poem like this is fun to say aloud in a group, getting louder at each BIG.']),
  ('Think about size and shape',['A laddoo is round, and many things around us are round, such as a ball, a coin, an orange, a wheel and the moon.','Some round things can be eaten, like an orange or a laddoo. Some cannot be eaten, like a ball or a wheel. We can sort them into two columns.','Big and small are words that tell us the size of a thing. Describing words like round, sweet, golden and soft tell us about a laddoo.','When you describe a thing, think of how it looks, how it feels and how it tastes.']),
  ('Blends cl, pl and bl',['In some words two letters come together at the start and make one sound.','Pl words are play, plum, plate and plant. Cl words are cloud, clock, clap and clean. Bl words are blue, blanket, black and blow.','Make a sentence with each word: I play in the park. The blue blanket is soft. A cloud floats in the sky.']),
  ('Animal partners',['Many animals have a male name and a female name.','A cock is a male bird and a hen is the female. A lion is male and a lioness is female.','A peacock is male and a peahen is female. A mare is a female horse. A bull is male and a cow is female. A drake is a male duck.','To match the pairs, ask: which is the male and which is the female of the same kind of animal?']),
  ('Float or sink',['Some things float on water and some things sink.','A piece of paper, a green leaf and a feather are light, so they float for a while.','A small stone, a spoon and an eraser are heavier for their size, so they sink. A pencil is light and floats.','Try this at home with a tub of water, and always have a grown-up near.']),
  ('Festivals and khichdi',['Festivals bring people together and help us stay close to nature and culture.','Khichdi is cooked with rice and lentils. It is a traditional dish for the harvest festival.','This festival has many names: Sankranti, Pongal, Lohri, Bihu and others. It is a time to thank the Sun God for a good harvest, and flying kites is popular.','Khichdi is made in many ways: Pongal in Tamil Nadu, bisi bele bhat in Karnataka, Gujarati khichdi in Gujarat and kichuri in West Bengal.'])],
 [('Match the animals: a cock and a ___ . Choose hen or cow.',[('A cock is a male bird.','We look for the female of the same kind of bird.'),('The female bird is the hen.','Cow is the female of the bull, not of the cock.'),('So a cock goes with a hen.','Pairs are the male and female of the same animal.')]),
  ('Which will float: a feather, a small stone, a spoon?',[('Ask whether the thing is light or heavy.','Light things float.'),('A feather is very light.','It floats.'),('A small stone and a spoon are heavy for their size.','They sink. Only the feather floats.')])],
 ('Tell a friend what the poem is about and why it is funny.',['Many small things become one big thing','Big laddoo, big child, big sea','The big child throws the laddoo and makes a splish-splash'],['The poem is about a real giant','The child eats the laddoo']),
 ['The poem imagines laddoos, children and seas becoming one big one.','Splish-splash is a sound word.','Cl, pl and bl are blends that start many words.','A cock goes with a hen, a lion with a lioness, a peacock with a peahen.','Light things float and heavy things sink.'],
 [M('1',1,'What does the poem imagine?','All the laddoos becoming one big laddoo',[('One laddoo becoming small','It is about becoming big'),('A laddoo made of stone','The poem is about size')],'Many small things become one big thing.'),
  M('2',1,'What happens at the end of the poem?','The big child throws the laddoo into the sea',[('The child eats the laddoo','It is thrown, not eaten'),('The sea dries up','A big splash is made')],'It ends with a big splish-splash.'),
  M('3',1,'What is splish-splash?','A sound word for water',[('The name of a sweet','It is a sound'),('A kind of fish','It is the sound of a splash')],'It copies the sound of water.'),
  M('4',1,'Which can be eaten?','An orange',[('A ball','A ball is not food'),('A wheel','A wheel is not food')],'An orange is round and can be eaten.'),
  M('5',2,'Which word starts with bl?','Blanket',[('Clock','Clock starts with cl'),('Plum','Plum starts with pl')],'Blanket starts with bl.'),
  M('6',2,'Which word starts with cl?','Cloud',[('Blue','Blue starts with bl'),('Play','Play starts with pl')],'Cloud starts with cl.'),
  M('7',2,'Which pair is correct?','Peacock and peahen',[('Lion and cow','They are not a pair'),('Mare and drake','A mare is a horse and a drake is a duck')],'The peacock is male and the peahen is female.'),
  M('8',2,'Which pair is male and female?','Lion and lioness',[('Hen and cow','They are different animals'),('Bull and peahen','They are different animals')],'A lion is male and a lioness is female.'),
  M('9',2,'Which thing floats on water?','A feather',[('A small stone','It sinks'),('A spoon','It sinks')],'A feather is light, so it floats.'),
  F('10',2,'Khichdi is cooked with rice and lentils.',True,'Rice and lentils are cooked together.'),
  S('11',2,'Which festival do we thank the Sun God for a good harvest?',['sankranti','pongal','makara sankranti','harvest festival'],'It is called Sankranti, Pongal and other names.'),
  M('12',3,'Why is the word BIG repeated in the poem?','To show how huge things become',[('Because the poet forgot','It is done on purpose'),('To make the poem short','It makes the poem longer')],'The repetition makes us feel the size.')],
 keep=['splish-splash','khichdi'])
